require_once __DIR__.'/../config/config.php';require_doctor();require_once __DIR__.'/../includes/doctor_clinical_service.php';header('Content-Type: application/json');$s=new DoctorClinicalService(getDB(),current_user());$action=$_GET['action']??$_POST['action']??'';
try{if($action==='summary')json_response(true,['data'=>$s->summary()]);if($action==='patients')json_response(true,['data'=>$s->patients($_GET['search']??'')]);if($action==='records')json_response(true,['data'=>$s->records((int)($_GET['patient_user_id']??0))]);if($action==='save'){if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);json_response(false,[],'Use POST.');}csrf_verify_or_die();$id=$s->save($_POST);json_response(true,['id'=>$id],'Consultation saved and audited.');}http_response_code(400);json_response(false,[],'Unsupported clinical operation.');}catch(PDOException $e){error_log('Doctor consultation: '.$e->getMessage());http_response_code(503);json_response(false,[],'Clinical data could not be saved or retrieved.');}catch(RuntimeException|InvalidArgumentException $e){http_response_code(409);json_response(false,[],$e->getMessage());}
